<script setup lang="ts">
import {devControlsEnabled} from "../../config/presentation";
import {parkContext} from '../../config/park';
import EmergencyPanel from './components/EmergencyPanel.vue';import {useEmergencyStore} from '../../store/useEmergencyStore';import './emergency.css';
import {computed,ref,onMounted,onBeforeUnmount,watch} from 'vue';import type {FloodForecast,FloodScenario} from '../../types/flood';import {floodScenarioLabels} from '../../types/flood';
import {useRealtimeStore} from '../../store/useRealtimeStore';import {floodApi} from '../../api/flood';import {simulationApi} from '../../api/realtime';import type {ParkRealtimeState} from '../../types/realtime';import {isParkRealtimeState} from '../../types/realtimeValidation';
import DigitalTwinScene from '../../components/digital-twin/DigitalTwinScene.vue';import FloodRiskCard from './components/FloodRiskCard.vue';import FloodForecastCard from './components/FloodForecastCard.vue';import FloodTrendChart from './components/FloodTrendChart.vue';import './flood.css';
const realtime=useRealtimeStore(),dev=devControlsEnabled;const emergency=useEmergencyStore(),emergencyOpen=ref(false);
const state=computed(()=>realtime.state?.flood),p03=computed(()=>realtime.getDeviceById('P03'));
const busy=ref(false),error=ref(''),forecast=ref<FloodForecast|null>(null),forecastError=ref(''),forecastLoading=ref(false);
const scenario=ref<FloodScenario>('extreme_rain'),people=ref(32),vehicles=ref(48),storage=ref<{available:boolean;message:string;lastSampleAt:string|null}|null>(null);
let alive=true,request:AbortController|undefined,timer:ReturnType<typeof setInterval>|undefined,generation=0;
async function refreshForecast(){if(!alive||realtime.connectionStatus!=='connected')return;const token=++generation;request?.abort();request=new AbortController();forecastLoading.value=true;const id=state.value?.scenarioId;
 try{const value=await floodApi.forecast(request.signal);if(alive&&token===generation&&id===state.value?.scenarioId){forecast.value=value;forecastError.value='';}}
 catch{if(alive&&token===generation&&!request.signal.aborted)forecastError.value='预测暂不可用，请检查连接。';}
 finally{if(alive&&token===generation)forecastLoading.value=false;}
}
async function checkStorage(){try{const value=await floodApi.storage();if(alive)storage.value=value;}catch{if(alive)storage.value={available:false,message:'快照存储连接失败',lastSampleAt:null};}}
async function command(action:()=>Promise<ParkRealtimeState>){if(busy.value)return;busy.value=true;error.value='';try{const result=await action();if(!isParkRealtimeState(result))throw new Error('invalid');if(alive){realtime.applyRealtimeState(result);void refreshForecast();void checkStorage();}}catch{if(alive)error.value='控制请求失败，请检查服务状态或开发模式。';}finally{busy.value=false;}}
function emergencyDemo(){if(window.confirm('当前操作仅作用于软件仿真环境，不控制真实设备。\n演示共 60 分钟，30–35 分钟雨势从 100 回落到 20 mm/h。'))void command(()=>floodApi.command('emergency-demo-start'));}
function competitionDemo(){window.dispatchEvent(new CustomEvent('twincity-demo-start',{detail:{scenario:'flood'}}));}
function demo(){if(window.confirm('将启动软件仿真事故场景，不影响真实设备。'))void command(()=>floodApi.command('demo-start'));}
watch(()=>state.value?.scenarioId,()=>{forecast.value=null;void refreshForecast();});
watch(()=>realtime.connectionStatus,status=>{if(status==='connected')void refreshForecast();});
onMounted(()=>{void refreshForecast();void checkStorage();timer=setInterval(()=>{void refreshForecast();void checkStorage();},10000);});
onBeforeUnmount(()=>{alive=false;generation++;request?.abort();clearInterval(timer);});
</script>
<template><div class="section-heading flood-heading"><div><span class="eyebrow">CAOHEJING TECH OASIS · FLOOD & EMERGENCY</span><h2>暴雨内涝推演中心</h2><p>{{parkContext.floodZone}} · 软件仿真区域</p></div><div class="flood-main-actions"><template v-if="dev"><button class="flood-primary" :disabled="busy" @click="demo">启动暴雨内涝推演</button><button :disabled="busy" @click="emergencyDemo">应急演示 · 暴雨后雨势回落</button></template><button v-else class="flood-primary" :disabled="busy" @click="competitionDemo">开始暴雨内涝演示</button><button data-testid="emergency-open" :disabled="!state?.scenarioId||state?.status==='completed'||(!dev&&(state?.riskScore??0)<60)" @click="emergencyOpen=true">进入应急方案推演</button><template v-if="dev"><button :disabled="busy||!state?.scenarioId||!realtime.state?.running" @click="command(()=>floodApi.command('stop'))">暂停场景</button><button :disabled="busy||state?.status==='completed'||realtime.state?.running" @click="command(simulationApi.start)">继续场景</button><button :disabled="busy" @click="command(()=>floodApi.command('reset'))">重置内涝场景</button></template></div></div><div class="simulation-steps"><span class="active"><b>01</b> 事故演化 <small>观测雨量、设备与积水</small></span><RouterLink to="/risk"><b>02</b> 未来预测 <small>物理模型与机器学习对照 →</small></RouterLink><button :disabled="!state?.scenarioId||state?.status==='completed'||(!dev&&(state?.riskScore??0)<60)" @click="emergencyOpen=true"><b>03</b> 应急方案 <small>同一基线 · 人工选择 →</small></button></div><p class="flood-disclaimer">软件仿真 · 简化水量平衡模型 · 非 CFD / 实际防洪设计模型，不用于真实安全决策</p><p v-if="error" role="alert">{{error}}</p><div v-if="state" class="flood-layout" data-testid="flood-page" :data-scenario="state.scenarioId??''" :data-status="state.status"><aside class="panel flood-parameters"><h3>场景参数 <small>{{floodScenarioLabels[state.scenario]}}</small></h3><div class="flood-status">{{state.status==='idle'?'待启动':state.status==='completed'?'演示时长已结束':state.running&&realtime.state?.running?'正在演化':'已暂停'}} · {{(state.elapsedSimulationSeconds/60).toFixed(1)}} / {{state.durationMinutes}} min</div><dl><div><dt>当前降雨</dt><dd data-testid="flood-rainfall" :data-value="state.rainfall">{{state.rainfall.toFixed(1)}} <small>mm/h</small></dd></div><div><dt>有效入流</dt><dd>{{state.surfaceInflow.toFixed(3)}} <small>m³/s</small></dd></div><div><dt>有效泵排水能力</dt><dd>{{state.effectivePumpCapacity.toFixed(3)}} <small>m³/s</small></dd></div><div><dt>实际总出流</dt><dd>{{state.outflow.toFixed(3)}} <small>m³/s</small></dd></div><div><dt>P03 效率</dt><dd data-testid="flood-p03-efficiency" :data-value="p03?.efficiency">{{p03?.efficiency.toFixed(1)}}%</dd></div><div><dt>P03 健康指数</dt><dd>{{p03?.health.toFixed(1)}}</dd></div><div><dt>人员 / 车辆</dt><dd>{{state.peopleCount}} / {{state.vehicleCount}}</dd></div></dl><p class="flood-source">天气和设备来自同一实时引擎。泵效率由设备退化模型产生。</p><div v-if="dev" class="flood-dev-controls"><h4>开发参数</h4><label>降雨情景<select v-model="scenario" aria-label="内涝降雨情景"><option v-for="(name,key) in floodScenarioLabels" :key="key" :value="key">{{name}}</option></select></label><button :disabled="busy" @click="command(()=>floodApi.start(scenario,people,vehicles))">启动手动情景</button><div class="flood-occupancy"><label>人员<input type="number" v-model.number="people" min="0" max="500" aria-label="B2 人员数量"/></label><label>车辆<input type="number" v-model.number="vehicles" min="0" max="300" aria-label="B2 车辆数量"/></label></div><button :disabled="busy" @click="command(()=>floodApi.exposure(people,vehicles))">更新暴露参数</button><label v-for="id in ['P01','P02']" :key="id">{{id}} 泵状态<select :aria-label="`${id} 内涝泵状态`" :value="realtime.getDeviceById(id)?.status==='standby'?'standby':realtime.getDeviceById(id)?.status==='offline'?'offline':'running'" :disabled="busy" @change="command(()=>simulationApi.device(id,($event.target as HTMLSelectElement).value as 'standby'|'running'|'offline'))"><option value="standby">待机</option><option value="running">运行</option><option value="offline">离线</option></select></label><label>P03 工况<select aria-label="内涝 P03 工况" :value="p03?.fault" :disabled="busy" @change="command(()=>simulationApi.fault('P03',($event.target as HTMLSelectElement).value as 'normal'|'bearing_degradation'))"><option value="normal">正常</option><option value="bearing_degradation">轴承退化</option></select></label><label>模拟速度<select aria-label="内涝模拟速度" :value="realtime.state?.speed" :disabled="busy" @change="command(()=>simulationApi.speed(Number(($event.target as HTMLSelectElement).value)))"><option :value="1">1×</option><option :value="5">5×</option><option :value="10">10×</option></select></label></div></aside><div class="flood-center"><DigitalTwinScene :realtime-state="realtime.state" :emergency-preview="emergency.previewTargets" flood-guidance/><div class="panel flood-event"><h3>当前事件 <small>演化状态 · 非处置工单</small></h3><p>{{state.scenarioId?`${parkContext.floodZone}内涝风险`:'尚未启动内涝演示'}}</p><p v-if="state.alarm" data-testid="flood-alarm" :data-id="state.alarm.id">{{state.alarm.message}}</p><p v-else>暂无内涝告警</p><small>{{storage?.available?'快照每 5 秒采样':'快照存储暂不可用'}} · {{storage?.message||'保留本次演化记录'}}</small></div><FloodTrendChart :points="realtime.floodHistory"/></div><aside class="flood-right"><FloodRiskCard :state="state"/><FloodForecastCard :forecast="forecast" :loading="forecastLoading" :error="forecastError" :stale="realtime.connectionStatus!=='connected'"/></aside></div><p v-else>等待实时状态…</p><EmergencyPanel v-if="emergencyOpen" @close="emergencyOpen=false"/></template>
